/* A playable memory based on the owner's photo and their own account of that day. */
const MEMORY_PHOTO='assets/beihai-memory-354c055e.jpg';
const memoryStory={title:'十一 · 琉璃阁前的我们',place:'北京 · 北海公园 · 琉璃阁',text:'十一的时候，我们一起去了北京。在北海公园的琉璃阁前，留下了这张合照。那天很开心。'};
function freshMemory(){return {active:false,complete:false,step:0,clues:new Set(),lastClue:'',order:[3,0,5,2,1,4],selected:null,moves:0,showOriginal:false,poses:{girl:{x:305,y:285,ready:false},boy:{x:720,y:285,ready:false}},replay:false}}
let memory=freshMemory(),memoryToken=0;
const memoryBaseRender=render,memoryBaseNext=next,memoryBaseReset=reset;
const memoryClues=[{id:'glass',label:'青绿的琉璃',x:565,y:93,detail:'青绿与金色，一层一层铺满墙面。这是那天留在照片里的颜色。'},{id:'door',label:'那道红色的门',x:273,y:212,detail:'那道红色门洞，也被我们一起留在了画面里。'},{id:'outfits',label:'我们的穿搭',x:666,y:302,detail:'白色连帽外套、粉紫色上衣，还有格纹长裙。就是照片里的我们。'}];
function memoryButton(id,text,cls='control'){return `<button id="${id}" class="${cls}">${text}</button>`}
function memoryHeading(){return `<div class="memory-heading"><div><div class="eyebrow">MEMORY 01 · 一张照片的回程</div><h2>${memoryStory.title}</h2></div><span class="memory-place">十一假期 · 北京</span></div><div class="memory-steps">${['找回细节','拼回合照','站回那一天','收进相册'].map((s,i)=>`<span class="${i===memory.step?'current':i<memory.step?'done':''}">${i<memory.step?'✓':i+1} · ${s}</span>`).join('')}</div>`}
function memoryFrame(content,controls='',speech=''){chapter.textContent='MEMORY 01 · 琉璃阁前的我们';document.querySelector('#skip').hidden=false;document.querySelector('#skip').textContent='预览回忆下一幕 →';document.querySelector('#hint').textContent='回忆章节 · 点击与拖动';app.innerHTML=`<section class="game memory-chapter">${memoryHeading()}${content}${speech?`<div class="dialog"><span class="portrait">✦</span><p id="speech">${speech}</p></div>`:''}<div class="controls">${controls}</div></section>`}
function courtyard(objects='',people=''){const shrines=Array.from({length:21},(_,i)=>{const x=455+(i%7)*48,y=132+Math.floor(i/7)*48;return `<g transform="translate(${x} ${y})"><path d="M-15 20V-4q0-23 15-23q15 0 15 23v24z" fill="#d5b082" stroke="#af9673"/><path d="M-10 15V-3q0-16 10-16q10 0 10 16v18z" fill="#80aca4"/><ellipse cy="-4" rx="4" ry="6" fill="#c5c6a4"/><path d="M-6 10q1-11 6-10q5 0 6 10" fill="#c1c5a5"/></g>`}).join('');return `<div class="memory-scene scene"><svg viewBox="0 0 1000 420" aria-label="由合照中的青绿琉璃墙与红门重现的回忆庭院"><defs>${daylightDefs}<pattern id="memoryTile" width="32" height="32" patternUnits="userSpaceOnUse"><rect width="32" height="32" fill="#75a9a2" stroke="#d3b987" stroke-width="2"/><path d="m16 3 13 13-13 13L3 16z" fill="none" stroke="#d5b883"/><circle cx="16" cy="16" r="4" fill="#d7c18d"/></pattern><linearGradient id="memorySky" x2="0" y2="1"><stop stop-color="#b5d4d1"/><stop offset="1" stop-color="#eae5ce"/></linearGradient></defs><rect width="1000" height="420" fill="url(#memorySky)"/><path d="M0 310h1000v110H0z" fill="#b7bfba"/><path d="M0 345h1000m-100 35H50m150-70-40 110m210-110-10 110m210-110 20 110m160-110 60 110" fill="none" stroke="#d2d6cb" stroke-width="2"/><rect x="115" y="56" width="770" height="245" fill="url(#memoryTile)" stroke="#b5ad88" stroke-width="6"/><rect x="155" y="37" width="690" height="39" fill="#76a79d"/><path d="M107 55h786m-755-20h724m-723-11h722" stroke="#d5bf91" stroke-width="6"/><path d="M135 24q365 18 730 0" fill="none" stroke="#4f8b83" stroke-width="16"/>${Array.from({length:28},(_,i)=>`<circle cx="${146+i*26}" cy="24" r="5" fill="#a2bdb0" stroke="#517f76"/>`).join('')}<path d="M172 301V175q0-96 94-96q94 0 94 96v126z" fill="#dec497" stroke="#aaa67c" stroke-width="5"/><path d="M191 301V176q0-75 75-75q75 0 75 75v125z" fill="#b36d7b"/><path d="M196 298V176q0-69 70-69" fill="none" stroke="#d29a9a" stroke-width="5"/><rect x="414" y="109" width="373" height="163" fill="#d7b38b"/>${shrines}<path d="M392 65v237m418-237v237" stroke="#9ab6a2" stroke-width="18"/><path d="M392 65v237m418-237v237" stroke="#d6c193" stroke-width="3"/><path d="M96 306h808m-825 13h842" stroke="#d8d6c5" stroke-width="12"/><g pointer-events="none" class="memory-dust">${[0,1,2,3,4].map((_,i)=>`<circle cx="${175+i*160}" cy="${80+i*38}" r="2" fill="#ffedbd"/>`).join('')}</g>${objects}${people}</svg></div>`}
function clueMarkup(){return memoryClues.map(c=>{const done=memory.clues.has(c.id);return `<g class="memory-clue ${done?'found':''}" data-clue="${c.id}" transform="translate(${c.x} ${c.y})" role="button" tabindex="0" aria-label="寻找${c.label}"><circle r="31" fill="transparent"/><circle class="clue-ring" r="19" fill="#fcebc41f" stroke="#fff0bb" stroke-width="1.5"/><path d="M0-10q0 10 10 10Q0 0 0 10Q0 0-10 0Q0 0 0-10" fill="#fff3c7"/>${done?'<path d="m-7 0 5 5 10-11" fill="none" stroke="#5b7d70" stroke-width="3"/>':''}</g>`}).join('')}
function findMemoryClue(id){if(memory.clues.has(id))return;memory.clues.add(id);memory.lastClue=memoryClues.find(c=>c.id===id).detail;chime(memory.clues.size===3);render()}
function memorySolved(){return memory.order.every((v,i)=>v===i)}
function renderClueScene(){memoryFrame(courtyard(clueMarkup(),character(480,291,true)+character(540,291,false)),`<div class="memory-clue-shortcuts">${memoryClues.map(c=>`<button class="control ${memory.clues.has(c.id)?'active':''}" data-clue="${c.id}">${memory.clues.has(c.id)?'✓ ':''}${c.label}</button>`).join('')}</div>${memoryButton('memoryContinue','拼回那张合照 →','primary')}`,memory.lastClue||'这条小路，通向十一那天。先在墙面、门洞和我们的穿搭里，找回三个细节。');const button=document.querySelector('#memoryContinue');button.disabled=memory.clues.size!==3;button.onclick=()=>{memory.step=1;chime();render()};document.querySelectorAll('[data-clue]').forEach(el=>{el.onclick=()=>findMemoryClue(el.dataset.clue);el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();findMemoryClue(el.dataset.clue)}}});document.querySelector('.memory-place').textContent=`已找到 ${memory.clues.size} / 3 个细节`}
function renderPhotoPuzzle(){const solved=memorySolved();const board=`<div class="memory-puzzle ${solved?'solved':''}">${memory.order.map((piece,slot)=>`<button class="memory-piece ${memory.selected===slot?'selected':''}" data-slot="${slot}" aria-label="位置${slot+1}，照片碎片${piece+1}" aria-pressed="${memory.selected===slot}" style="background-image:url('${MEMORY_PHOTO}');background-position:${piece%2*100}% ${Math.floor(piece/2)*50}%"><span>${slot+1}</span></button>`).join('')}${memory.showOriginal?`<img class="memory-original-hint" src="${MEMORY_PHOTO}" alt="原始合照，供拼图提示"/>`:''}</div>`;memoryFrame(`<div class="memory-layout"><div class="memory-copy"><div class="eyebrow">SIX PIECES, ONE DAY</div><h3>${solved?'那一天，慢慢回来了。':'有些日子，值得再拼一次。'}</h3><p>屋檐在上，石板路在下。<br>把零散的六片画面，拼回我们站在一起的样子。</p><p class="memory-instruction">轻点两块照片，就能交换位置。<br>需要时可以看看原图，没有时间限制。</p><div class="memory-puzzle-meta">已交换 ${memory.moves} 次</div></div>${board}</div>`,solved?memoryButton('memoryContinue','走回照片里的位置 →','primary'):`${memoryButton('memoryHint',memory.showOriginal?'收起原图':'看一眼原图','control')}${memoryButton('memoryRetry','重新拼一次','text')}`,solved?'拼好了。这张照片里，有十一的北京，也有站在一起的我们。':'不用着急。先认出琉璃阁的屋檐，再把两个人放到一起。');document.querySelectorAll('[data-slot]').forEach(el=>el.onclick=()=>{if(solved||memory.showOriginal)return;const i=Number(el.dataset.slot);if(memory.selected===null){memory.selected=i;render();return}if(memory.selected===i){memory.selected=null;render();return}const j=memory.selected;[memory.order[i],memory.order[j]]=[memory.order[j],memory.order[i]];memory.moves++;memory.selected=null;if(memorySolved())chime(true);render()});if(solved)document.querySelector('#memoryContinue').onclick=()=>{memory.step=2;render()};else{document.querySelector('#memoryHint').onclick=()=>{memory.showOriginal=!memory.showOriginal;memory.selected=null;render()};document.querySelector('#memoryRetry').onclick=()=>{memory.order=[3,0,5,2,1,4];memory.selected=null;memory.moves=0;memory.showOriginal=false;render()}}}
function photoPosePosition(id){const p=memory.poses[id];document.querySelector('#memory-'+id)?.setAttribute('transform',`translate(${p.x} ${p.y})`);document.querySelector('#pose-target-'+id)?.classList.toggle('placed',p.ready)}
function renderPoseScene(){const ready=memory.poses.girl.ready&&memory.poses.boy.ready;const objects=`<g id="pose-target-girl" class="pose-target ${memory.poses.girl.ready?'placed':''}" transform="translate(474 292)"><ellipse cy="44" rx="26" ry="8"/><text y="66" text-anchor="middle">我站这里</text></g><g id="pose-target-boy" class="pose-target ${memory.poses.boy.ready?'placed':''}" transform="translate(530 292)"><ellipse cy="44" rx="26" ry="8"/><text y="66" text-anchor="middle">你在身边</text></g>`;const people=`<g id="memory-girl" class="memory-draggable" role="button" tabindex="0" aria-label="把女生放到左侧发光脚印上">${character(0,0,true)}</g><g id="memory-boy" class="memory-draggable" role="button" tabindex="0" aria-label="把男生放到右侧发光脚印上">${character(0,0,false)}</g>`;memoryFrame(courtyard(objects,people),memoryButton('memoryShutter',ready?'一起按下快门 ✦':'让我们站回那一天','primary'),'把两个小人拖到发光的脚印上。也可以轻点小人，让它自己站好。');const shutter=document.querySelector('#memoryShutter');shutter.disabled=!ready;shutter.onclick=memoryShutter;const svg=document.querySelector('.memory-scene svg');for(const id of ['girl','boy']){const el=document.querySelector('#memory-'+id);el.insertAdjacentHTML('afterbegin','<rect x="-35" y="-65" width="70" height="115" fill="transparent" pointer-events="all"/>');photoPosePosition(id);let drag=null;const target={x:id==='girl'?474:530,y:292};const place=()=>{memory.poses[id]={...target,ready:true};chime();render()};el.onpointerdown=e=>{if(memory.poses[id].ready)return;e.preventDefault();el.setPointerCapture(e.pointerId);drag={id:e.pointerId,x:e.clientX,y:e.clientY,moved:false}};el.onpointermove=e=>{if(!drag||drag.id!==e.pointerId)return;e.preventDefault();if(Math.hypot(e.clientX-drag.x,e.clientY-drag.y)>7)drag.moved=true;const p=svg.createSVGPoint();p.x=e.clientX;p.y=e.clientY;const q=p.matrixTransform(svg.getScreenCTM().inverse());memory.poses[id].x=clamp(q.x,200,800);memory.poses[id].y=clamp(q.y+18,250,306);photoPosePosition(id)};el.onpointerup=e=>{if(!drag||drag.id!==e.pointerId)return;const was=drag;drag=null;if(!was.moved||Math.hypot(memory.poses[id].x-target.x,memory.poses[id].y-target.y)<48)place();else say('再靠近发光脚印一点，就能回到照片里的位置。')};el.onpointercancel=()=>{drag=null};el.onlostpointercapture=()=>{drag=null};el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();place()}}}}
function memoryShutter(){if(!(memory.poses.girl.ready&&memory.poses.boy.ready))return;const token=++memoryToken;const sceneEl=document.querySelector('.memory-scene');sceneEl.insertAdjacentHTML('beforeend','<div class="memory-flash" aria-hidden="true"></div>');document.querySelector('#memoryShutter').disabled=true;chime(true);setTimeout(()=>{if(token!==memoryToken||!memory.active)return;memory.step=3;render()},motionOff()?0:500)}
function openMemoryPhoto(){if(document.querySelector('#memoryPhotoDialog'))return;const dialog=document.createElement('dialog');dialog.id='memoryPhotoDialog';dialog.className='memory-photo-dialog';dialog.innerHTML=`<button id="closeMemoryPhoto" aria-label="关闭合照">关闭 ×</button><img src="${MEMORY_PHOTO}" alt="十一在北京北海公园琉璃阁前拍摄的双人合照"/>`;document.body.append(dialog);dialog.querySelector('button').onclick=()=>dialog.close();dialog.onclick=e=>{if(e.target===dialog)dialog.close()};dialog.onclose=()=>dialog.remove();dialog.showModal()}
function renderMemoryReveal(){memoryFrame(`<div class="memory-layout memory-reveal"><div class="memory-copy"><div class="eyebrow">THE DAY WE KEPT</div><h3>原来，<br>是我们很开心的那一天。</h3><p class="memory-story">${memoryStory.text.replaceAll('。','。<br>')}</p><div class="memory-story-stamp">${memoryStory.place}</div><p class="memory-instruction">点开照片，可以再看清楚一点。</p></div><figure class="memory-photo"><button id="memoryEnlarge" aria-label="放大查看真实合照"><img src="${MEMORY_PHOTO}" alt="十一在北京北海公园琉璃阁前拍摄的合照"/></button><figcaption>十一假期 · 和你一起去北京</figcaption></figure></div>`,`${memoryButton('memoryCollect',memory.replay?'回到旅程 →':'收好这段回忆，继续走 →','primary')}${memoryButton('memoryReplay','再走一遍这段回忆','text')}`,'这张照片会跟着我们一起回家，放进最后那间小屋里。');document.querySelector('#memoryEnlarge').onclick=openMemoryPhoto;document.querySelector('#memoryReplay').onclick=()=>{const completed=memory.complete;memory=freshMemory();memory.active=true;memory.complete=completed;memory.replay=true;render()};document.querySelector('#memoryCollect').onclick=collectMemory}
function collectMemory(){const replay=memory.replay;memory.active=false;memory.complete=true;chime(true);if(replay){render();return}memoryBaseNext()}
function openMemory(replay=false){++memoryToken;cancelAnimationFrame(frame);cancelAnimationFrame(walkFrame);clearCoopTouches();holding.clear();transitioning=false;if(stage===0){stage=1;met=true}memory.active=true;memory.replay=replay;render()}
function renderMemory(){cancelAnimationFrame(frame);cancelAnimationFrame(walkFrame);if(memory.step===0)renderClueScene();else if(memory.step===1)renderPhotoPuzzle();else if(memory.step===2)renderPoseScene();else renderMemoryReveal()}
function mountMemoryFrame(){if(!memory.complete||stage!==5||unwrapped)return;const svg=document.querySelector('.scene svg');if(!svg)return;const g=document.createElementNS('http://www.w3.org/2000/svg','g');g.id='collectedMemoryFrame';g.setAttribute('role','button');g.setAttribute('tabindex','0');g.setAttribute('aria-label','查看收藏在小屋里的琉璃阁合照');g.innerHTML=`<rect x="707" y="102" width="91" height="140" rx="5" fill="#d9ba8b"/><image href="${MEMORY_PHOTO}" x="714" y="109" width="77" height="126" preserveAspectRatio="xMidYMid slice"/><path d="M715 241h76" stroke="#9f8267" stroke-width="3"/>`;svg.insertBefore(g,svg.querySelector('#boy'));g.onclick=openMemoryPhoto;g.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();openMemoryPhoto()}}}
render=function(){if(memory.active){renderMemory();return}memoryBaseRender();if(stage===1&&met){const controls=document.querySelector('.controls');const b=document.createElement('button');b.id='memoryStart';b.className='control memory-entry';b.textContent=memory.complete?'再看看我们的回忆 ♡':'这里藏着一段我们的回忆 ✦';b.onclick=()=>openMemory(memory.complete);controls.prepend(b);if(!memory.complete)document.querySelector('#depart').textContent='沿着回忆的小路走 →'}mountMemoryFrame()};
next=function(){if(stage===1&&met&&!memory.complete&&!memory.active){openMemory();return}memoryBaseNext()};
reset=function(){++memoryToken;memory=freshMemory();document.querySelector('#memoryPhotoDialog')?.close();memoryBaseReset()};document.querySelector('#restart').onclick=reset;document.querySelector('#brand').onclick=e=>{e.preventDefault();reset()};
document.querySelector('#skip').onclick=()=>{if(memory.active){++memoryToken;if(memory.step===0){memory.clues=new Set(memoryClues.map(c=>c.id));memory.step=1}else if(memory.step===1){memory.order=[0,1,2,3,4,5];memory.step=2}else if(memory.step===2){memory.step=3}else{collectMemory();return}render();return}++journeyToken;transitioning=false;cancelAnimationFrame(walkFrame);clearCoopTouches();baseAdvance()};
if(new URLSearchParams(location.search).get('chapter')==='memory')openMemory();else render();
